from ute_ipsec.fsm_access import FsmAccess
from ute_admin import ute_admin
import subprocess


class TrsConfig(object):
    """All TRS CLI operations will be done in this class"""

    def __init__(self):
        self.fsm_access = FsmAccess()
        self.ute_admin = ute_admin()

    def search_trs_parameter(self, search_expression):
        """Generates TRS scf file, searches the file with the expression provided and returns search result"""
        self.fsm_access.execute_command('/opt/trs/bin/objcli generate_scf')
        command = "cat /tmp/transport/ftp/config.xml | grep {}".format(search_expression)
        result = self.fsm_access.execute_command(command)

        return result[0] if isinstance(result, tuple) else result

    def search_trs_parameter_soam(self, search_expression):
        """Generates SOAM scf file, searches the file with the expression provided and returns search result"""
        self.ute_admin.setup_admin(bts_host="192.168.255.129", bts_port=443, use_ssl=True)
        self.ute_admin.collect_scf("/tmp/scfc.xml", export_type="configurationAndRuntimeObjects")
        self.ute_admin.teardown_admin()
        command = "cat /tmp/scfc.xml | grep {}".format(search_expression)
        result = subprocess.check_output(command, shell=True)
        # result = self.fsm_access.execute_command(command)

        return result[0] if isinstance(result, tuple) else result

    def is_vlan_existing(self, ip_version):
        """Returns True If Vlans are already existing """
        if ip_version == 4:
            search_expression = "'localIpAddr\">10.0.3.210' | wc -l"
        elif ip_version == 6:
            search_expression = "'localIpv6Addr\">fc00::3:7' | wc -l"
        result = self.search_trs_parameter(search_expression)
        return bool(int(result) >= 1)
